svg.script:
/* rows + phase-locked hands are generated so the plate stays exact */
var NS="http://www.w3.org/2000/svg";
var D=[[0.2408,-118,-168],[0.6152,-32,-24],[1.0000,96,76],[1.8808,-148,-134],
       [11.862,140,104],[29.457,-72,-70],[84.02,52,18],[164.79,-118,128]];
/* phase angle of each world at t=0, taken from the artwork above */
var PH=[168,-32,96,-148,140,-72,52,-118];
var root=document.getElementById("trows");
for(var i=0;i<D.length;i++){
  var y=126+i*52, T=D[i][0]*12;
  var nm=["MERCURY","VENUS","EARTH","MARS","JUPITER","SATURN","URANUS","NEPTUNE"][i];
  var t=document.createElementNS(NS,"text");
  t.setAttribute("x","26");t.setAttribute("y",y+4);t.setAttribute("class","lbl");
  t.setAttribute("font-size","12.5");t.textContent=nm;root.appendChild(t);
  var v=document.createElementNS(NS,"text");
  v.setAttribute("x","246");v.setAttribute("y",y+4);v.setAttribute("class","num");
  v.setAttribute("text-anchor","end");v.setAttribute("font-size","13");
  v.textContent=(D[i][0]<10?D[i][0].toFixed(4):D[i][0].toFixed(3));root.appendChild(v);
  var g=document.createElementNS(NS,"g");
  g.setAttribute("transform","translate(232,"+(y-4)+")");
  var c=document.createElementNS(NS,"circle");
  c.setAttribute("r","15");c.setAttribute("fill","none");c.setAttribute("stroke","#5d4720");
  c.setAttribute("stroke-width",".8");c.setAttribute("stroke-dasharray","1 2.2");c.setAttribute("opacity",".7");g.appendChild(c);
  var h=document.createElementNS(NS,"g");
  h.setAttribute("class","hand");
  h.setAttribute("style","animation-duration:"+T.toFixed(2)+"s;animation-delay:"+(-T*(PH[i]%360)/360).toFixed(2)+"s;transform-origin:0 0");
  var p=document.createElementNS(NS,"path");
  p.setAttribute("d","M0 0L0-12");p.setAttribute("stroke","#f0d896");p.setAttribute("stroke-width","1.6");p.setAttribute("stroke-linecap","round");
  h.appendChild(p);g.appendChild(h);
  var dot=document.createElementNS(NS,"circle");dot.setAttribute("r","2");dot.setAttribute("fill","url(#brass)");g.appendChild(dot);
  root.appendChild(g);
}
